<script setup lang="ts">
import {ref,computed,nextTick} from 'vue'
import {ElButton} from 'element-plus'
import 'element-plus/es/components/button/style/css'
import type {Course,SceneObject} from '../player/model'
import StepEditor from './StepEditor.vue'
import EditorCanvas from './EditorCanvas.vue'
import ObjectProperties from './ObjectProperties.vue'
import {kinds,uid,scene as newScene,object,ensureComponent,writePosition,blockers} from './adapter'
const props=defineProps<{course:Course}>(),emit=defineEmits<{change:[c:Course];message:[s:string]}>()
const ci=ref(0),si=ref(0),selected=ref(''),kind=ref('node'),source=ref(''),target=ref('')
const chapter=computed(()=>props.course.chapters[ci.value]||props.course.chapters[0]!),scene=computed(()=>chapter.value.scenes[si.value]||chapter.value.scenes[0]!),chosen=computed(()=>scene.value.objects.find(o=>o.id===selected.value))
function edit(fn:(c:Course,s:typeof scene.value)=>void){const copy=JSON.parse(JSON.stringify(props.course));fn(copy,copy.chapters[ci.value]?.scenes[si.value]||copy.chapters[0].scenes[0]);emit('change',copy)}
function courseField(k:'summary'|'category',e:Event){edit(c=>c[k]=(e.target as HTMLInputElement).value)}
function addChapter(){edit(c=>{const s=newScene();ensureComponent(c,s.objects[0]!);c.chapters.push({id:uid('chapter'),title:'新章节',scenes:[s]})});ci.value=props.course.chapters.length;si.value=0;selected.value=''}
function addScene(){edit(c=>{const s=newScene();ensureComponent(c,s.objects[0]!);c.chapters[ci.value]!.scenes.push(s)});si.value=chapter.value.scenes.length;selected.value=''}
function swap(items:any[],i:number,delta:number){if(i+delta<0||i+delta>=items.length)return;[items[i],items[i+delta]]=[items[i+delta],items[i]]}
function delChapter(){if(props.course.chapters.length===1)return emit('message','课程至少保留一个章节');if(!confirm('删除本章节及全部场景、对象和教学步骤？此操作将在保存后持久化。'))return;edit(c=>c.chapters.splice(ci.value,1));ci.value=0;si.value=0;selected.value=''}
function delScene(){if(chapter.value.scenes.length===1)return emit('message','章节至少保留一个场景');if(!confirm('删除本场景及全部对象和教学步骤？'))return;edit(c=>c.chapters[ci.value]!.scenes.splice(si.value,1));si.value=0;selected.value=''}
function addObject(){if(kind.value==='edge')return connect(source.value,target.value);if(kind.value==='image'&&!props.course.assets.length)return emit('message','请先上传并加入图片资源');const o=object(kind.value,props.course.assets[0]?.id);edit((c,s)=>{s.objects.push(o);ensureComponent(c,o)});selected.value=o.id}
function connect(a:string,b:string){if(!a||!b||a===b)return emit('message','请选择两个不同的对象作为连线端点');const o=object('edge');o.content.source=a;o.content.target=b;o.content.label='连接';edit((c,s)=>{s.objects.push(o);ensureComponent(c,o)});selected.value=o.id}
function remove(){if(!chosen.value)return;const refs=blockers(scene.value,selected.value);if(refs.length)return emit('message','不能删除：仍被引用。请先处理以下引用：\n'+refs.join('\n'));if(scene.value.objects.length===1)return emit('message','场景至少保留一个对象');edit((_,s)=>{s.objects=s.objects.filter(o=>o.id!==selected.value)});selected.value=''}
function update(o:SceneObject){if(chosen.value?.content.visual&&(!o.content.visual||!o.content.address)&&scene.value.objects.some(x=>x.content.packet?.source===o.id||x.content.packet?.target===o.id))return emit('message','设备仍被 TCP 报文引用，请保留外观和地址');edit((c,s)=>{s.objects[s.objects.findIndex(x=>x.id===o.id)]=o;if(o.content.visual||o.content.packet)c.components.find(x=>x.type==='flow')!.version='1.1.0'})}
function removeAsset(id:string){const refs=props.course.chapters.flatMap(c=>c.scenes.flatMap(s=>s.objects.filter(o=>o.content.assetId===id).map(o=>s.title+' / '+o.content.label)));if(refs.length)return emit('message','资源仍被引用：'+refs.join('、')+'；请先替换图片资源');edit(c=>{c.assets=c.assets.filter(a=>a.id!==id)})}
const timeline=ref<InstanceType<typeof StepEditor>>()
async function locate(path:string){
 const p=path.split('/')
 const num=(name:string)=>p.includes(name)?Number(p[p.indexOf(name)+1]):0
 ci.value=num('chapters');si.value=num('scenes')
 selected.value=p.includes('objects')?scene.value.objects[num('objects')]?.id:''
 await nextTick()
 if(p.includes('steps')){await timeline.value?.locate(num('steps'),num('actions'),!p.includes('actions')&&p.at(-1)==='durationMs'?'stepDuration':p.at(-1)!);return}
 const selector=p.includes('objects')?'.properties input':p.includes('scenes')?'[aria-label="场景标题"]':p.includes('chapters')?'[aria-label="章节标题"]':'[aria-label="课程标题"]'
 document.querySelector<HTMLElement>(selector)?.focus()
}
defineExpose({locate})
</script>
<template><div class="course-info"><label>简介<textarea aria-label="课程简介" :value="course.summary" @input="courseField('summary',$event)"/></label><label>分类<select aria-label="课程分类" :value="course.category" @change="courseField('category',$event)"><option value="network">网络协议</option><option value="business">业务流程</option><option value="math">数学知识</option><option value="manufacturing">生产工艺</option></select></label></div>
<div class="structure"><label>章节<select aria-label="编辑章节" v-model="ci" @change="si=0;selected=''"><option v-for="(c,i) in course.chapters" :value="i">{{i+1}}. {{c.title}}</option></select></label><label>章节标题<input aria-label="章节标题" :value="chapter.title" @input="edit(c=>c.chapters[ci]!.title=($event.target as HTMLInputElement).value)"></label><ElButton @click="addChapter">新增章节</ElButton><button @click="edit(c=>swap(c.chapters,ci,-1));ci=Math.max(0,ci-1)">章节上移</button><button @click="edit(c=>swap(c.chapters,ci,1));ci=Math.min(course.chapters.length-1,ci+1)">章节下移</button><button @click="delChapter">删除章节</button>
<label>场景<select aria-label="编辑场景" v-model="si" @change="selected=''"><option v-for="(s,i) in chapter.scenes" :value="i">{{i+1}}. {{s.title}}</option></select></label><label>场景标题<input aria-label="场景标题" :value="scene.title" @input="edit((_,s)=>s.title=($event.target as HTMLInputElement).value)"></label><ElButton @click="addScene">新增场景</ElButton><button @click="edit(c=>swap(c.chapters[ci]!.scenes,si,-1));si=Math.max(0,si-1)">场景上移</button><button @click="edit(c=>swap(c.chapters[ci]!.scenes,si,1));si=Math.min(chapter.scenes.length-1,si+1)">场景下移</button><button @click="delScene">删除场景</button></div>
<div class="object-tools"><select aria-label="新对象类型" v-model="kind"><option v-for="(label,k) in kinds" :value="k">{{label}}</option></select><template v-if="kind==='edge'"><select aria-label="新连线起点" v-model="source"><option value="">起点</option><option v-for="o in scene.objects.filter(x=>x.type!=='edge')" :value="o.id">{{o.content.label}}</option></select><select aria-label="新连线终点" v-model="target"><option value="">终点</option><option v-for="o in scene.objects.filter(x=>x.type!=='edge')" :value="o.id">{{o.content.label}}</option></select></template><ElButton type="primary" @click="addObject">添加对象</ElButton><select aria-label="编辑对象" v-model="selected"><option value="">选择对象</option><option v-for="o in scene.objects" :value="o.id">{{o.content.label}} · {{o.type}}</option></select><button @click="remove" :disabled="!chosen">删除对象</button><button @click="edit((_,s)=>swap(s.objects,s.objects.findIndex(o=>o.id===selected),-1))" :disabled="!chosen">对象上移</button><button @click="edit((_,s)=>swap(s.objects,s.objects.findIndex(o=>o.id===selected),1))" :disabled="!chosen">对象下移</button></div>
<div class="editor-grid"><div><div class="canvas-size"><label v-for="k in ['width','height']">画布{{k==='width'?'宽':'高'}}<input :aria-label="'画布'+(k==='width'?'宽':'高')" type="number" min="1" max="100000" :value="scene.canvas[k as 'width'|'height']" @input="edit((_,s)=>s.canvas[k as 'width'|'height']=Number(($event.target as HTMLInputElement).value))"></label></div><EditorCanvas :key="scene.id" :scene="scene" :selected="selected" @select="selected=$event" @move="(id,p)=>edit((_,s)=>writePosition(s,id,p))" @connect="connect"/><small>初始隐藏对象以虚线显示，方便编辑。</small></div><ObjectProperties v-if="chosen" :key="chosen.id" :object="chosen" :scene="scene" :course="course" @change="update"/><p v-else>选择画布对象以编辑属性。</p></div>
<StepEditor ref="timeline" :key="scene.id" :scene="scene" @change="steps=>edit((_,s)=>s.steps=steps)"/><details><summary>课程资源（移除仅解除本课引用）</summary><div v-for="a in course.assets" class="asset-row"><input aria-label="资源用途" :value="a.purpose" @input="edit(c=>c.assets.find(x=>x.id===a.id)!.purpose=($event.target as HTMLInputElement).value)"><a :href="'/api/v1/assets/'+a.id" target="_blank">{{a.id}}</a><button @click="removeAsset(a.id)">移除资源引用</button></div></details></template>
<style scoped>.course-info{display:grid;grid-template-columns:3fr 1fr;gap:12px}.course-info textarea{min-height:65px}.structure{display:flex;flex-wrap:wrap;gap:6px;align-items:center;border-block:1px solid #d5e0d9;padding:8px 0}.structure label{width:170px}.object-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:14px 0}.object-tools select{width:auto;max-width:250px}.editor-grid{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:12px}.canvas-size{display:flex;gap:10px}.canvas-size label{display:flex;align-items:center;gap:8px}.canvas-size input{width:100px}.asset-row{display:flex;gap:12px;align-items:center}.asset-row input{max-width:260px}small{display:block;margin-top:10px;color:#587061}@media(max-width:1050px){.editor-grid{grid-template-columns:1fr}}</style>
